using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Globalization;
using UnityEngine;using UnityEngine.Rendering;using UnityEditor;
namespace MapSharedProps.EditorTools {
// 独立した任意拡張。不正な巣が既存小物の生成を止めない。
public static class MineCobwebV1 {
 [Serializable]public class Maps{public int width,height;public string colour;}
 [Serializable]public class Data{public int version;public string units,axes;public float cutoff;public Maps textures;public SmallPropsV1.Asset[] assets;}
 static void Check(bool b,string s){if(!b)throw new InvalidDataException("mine cobweb: "+s);}
 static bool Finite(float v)=>!float.IsNaN(v)&&!float.IsInfinity(v);
 static void Floats(float[] a,int n){Check(a!=null&&a.Length==n&&a.All(Finite),"finite array");}
 public static Data Optional(Data d){if(d==null||(d.version==0&&d.assets==null))return null;try{
  Check(d.version==1&&d.units=="metres"&&d.axes=="Unity X/Y/Z","header");Check(d.assets!=null&&d.assets.Length<=1&&d.textures!=null&&d.textures.width==512&&d.textures.height==512,"bounded set");Check(Finite(d.cutoff)&&Mathf.Abs(d.cutoff-.12f)<1e-5,"alpha cutoff");
  foreach(var a in d.assets){Check(a!=null&&a.id=="mine_cobweb"&&a.assetKey=="tdj/mine_cobweb"&&a.material=="mineCobweb","identity");int n=a.positions?.Length/3??0;Check(n>0&&n<=2000&&a.positions.Length==n*3,"mesh bound");Floats(a.positions,n*3);Floats(a.normals,n*3);Floats(a.colors,n*3);Floats(a.uv,n*2);Floats(a.glow,n);Check(a.positions.All(v=>Mathf.Abs(v)<=3)&&a.normals.All(v=>Mathf.Abs(v)<=1.001f)&&a.colors.All(v=>v==1)&&a.glow.All(v=>v==0)&&a.uv.All(v=>v>=0&&v<=1),"mesh values");Check(a.triangles!=null&&a.triangles.Length>0&&a.triangles.Length<=6000&&a.triangles.Length%3==0&&a.triangles.All(v=>v>=0&&v<n),"indices");Check(Finite(a.radius)&&a.radius>=0&&a.radius<=3&&Finite(a.height)&&a.height>0&&a.height<=3&&Mathf.Abs(a.groundSink+1.65f)<1e-5,"catalog");if(!a.shape&&a.radius>0){Check(a.circleColliders!=null&&a.circleColliders.Length>0&&a.circleColliders.Length<=32,"proxies");foreach(var c in a.circleColliders){Floats(c.center,3);Check(c.center.All(v=>Mathf.Abs(v)<=3)&&Finite(c.radius)&&Mathf.Abs(c.radius-a.radius)<1e-6&&Finite(c.height)&&Mathf.Abs(c.height-a.height)<1e-6,"proxy contract");}}}
  Check(d.textures.colour!=null&&d.textures.colour.Length<1500000,"image size");var bytes=Convert.FromBase64String(d.textures.colour);Check(bytes.Length>=33&&bytes[0]==137&&bytes[1]==80&&bytes[2]==78&&bytes[3]==71&&bytes[4]==13&&bytes[5]==10&&bytes[6]==26&&bytes[7]==10&&bytes[12]==73&&bytes[13]==72&&bytes[14]==68&&bytes[15]==82&&bytes[16]==0&&bytes[17]==0&&bytes[18]==2&&bytes[19]==0&&bytes[20]==0&&bytes[21]==0&&bytes[22]==2&&bytes[23]==0,"PNG header");var t=new Texture2D(2,2,TextureFormat.RGBA32,false,true);try{Check(ImageConversion.LoadImage(t,bytes)&&t.width==512&&t.height==512,"PNG decode");}finally{UnityEngine.Object.DestroyImmediate(t);}return d;
 }catch(Exception e)when(e is InvalidDataException||e is FormatException||e is ArgumentException||e is NullReferenceException){Debug.LogWarning("Optional mine cobweb ignored; existing assets retained: "+e.Message);return null;}}
 static float Number(string s){var v=float.Parse(s,CultureInfo.InvariantCulture);Check(Finite(v),"placement finite");return v;}
 public static int Build(string directory,string folder,Transform parent,Dictionary<string,GameObject> prefabs,SmallPropsV1.Data data){var d=data.mineCobwebV1;if(d==null||d.assets.Length==0)return 0;
  var image=SharedImportCache.Image(Convert.FromBase64String(d.textures.colour),".png",true,true,TextureWrapMode.Clamp,FilterMode.Trilinear,2,512);var imp=(TextureImporter)AssetImporter.GetAtPath(AssetDatabase.GetAssetPath(image));if(!imp.mipMapsPreserveCoverage||!imp.alphaIsTransparency||Mathf.Abs(imp.alphaTestReferenceValue-d.cutoff)>1e-5){imp.mipMapsPreserveCoverage=true;imp.alphaTestReferenceValue=d.cutoff;imp.alphaIsTransparency=true;imp.SaveAndReimport();}
  var shader=Shader.Find("Universal Render Pipeline/Lit");Check(shader&&shader.isSupported,"URP Lit");string path=folder+"/mine-cobweb-shared.mat";var material=AssetDatabase.LoadAssetAtPath<Material>(path);if(!material){Check(!File.Exists(path)&&!File.Exists(path+".meta"),"occupied material");material=new Material(shader){name="Dusty old cobweb",enableInstancing=true};AssetDatabase.CreateAsset(material,path);}material.shader=shader;material.SetColor("_BaseColor",Color.white);material.SetTexture("_BaseMap",image);material.SetFloat("_Metallic",0);material.SetFloat("_Smoothness",.09f);material.SetFloat("_AlphaClip",1);material.SetFloat("_Cutoff",d.cutoff);material.SetFloat("_Surface",0);material.SetFloat("_Cull",2);material.SetFloat("_ZWrite",1);material.SetFloat("_AlphaToMask",1);material.EnableKeyword("_ALPHATEST_ON");material.DisableKeyword("_SURFACE_TYPE_TRANSPARENT");material.DisableKeyword("_EMISSION");material.renderQueue=2450;material.SetOverrideTag("RenderType","TransparentCutout");EditorUtility.SetDirty(material);
  foreach(var a in d.assets){var mesh=SmallPropsV1.MeshOf(a.positions,a.normals,a.colors,a.triangles,a.glow);var uv=new Vector2[a.uv.Length/2];for(int i=0;i<uv.Length;i++)uv[i]=new Vector2(a.uv[i*2],1-a.uv[i*2+1]);mesh.uv=uv;mesh.RecalculateTangents();mesh=SharedImportCache.StoreMesh(mesh,"mine-cobweb/1\n"+JsonUtility.ToJson(a));var root=new GameObject(a.id);root.AddComponent<MeshFilter>().sharedMesh=mesh;var renderer=root.AddComponent<MeshRenderer>();renderer.sharedMaterial=material;renderer.shadowCastingMode=ShadowCastingMode.Off;renderer.receiveShadows=true;if(a.radius>0)SmallPropsV1.Collider(root,a,mesh);prefabs.Add(a.id,PrefabUtility.SaveAsPrefabAsset(root,folder+"/small-"+a.id+".prefab"));UnityEngine.Object.DestroyImmediate(root);}
  int placed=0;foreach(var line in File.ReadAllLines(Path.Combine(directory,"props.csv"))){var row=line.Split(',');if(row.Length!=11||!d.assets.Any(a=>a.id==row[1]&&a.assetKey==row[2]))continue;float sx=Number(row[7]),sy=Number(row[8]);Check(sx>0&&sy>0,"positive scale");var obj=(GameObject)PrefabUtility.InstantiatePrefab(prefabs[row[1]],parent);obj.name=row[0];obj.transform.localPosition=new Vector3(Number(row[3]),Number(row[4]),Number(row[5]));obj.transform.localRotation=Quaternion.Euler(0,Number(row[6]),0);obj.transform.localScale=new Vector3(sx,sy,sx);placed++;}return placed;
 }
}}
